import * as T from './vendor/three.module.js';
import {DepthRenderer} from './chess-engine.js?v=depot-v17';
export function createPrimitiveEngine(){const scene=new T.Scene(),camera=new T.PerspectiveCamera(40,16/9,.1,100);camera.position.set(4,3,7);camera.lookAt(0,0,0);scene.add(new T.AmbientLight('#ffffff',1.5));const key=new T.DirectionalLight('#e5dcff',3);key.position.set(4,6,5);scene.add(key);const fill=new T.DirectionalLight('#ffa76b',2);fill.position.set(-4,2,-3);scene.add(fill);let renderer;try{renderer=new T.WebGLRenderer({alpha:true,antialias:true});renderer.setSize(960,540)}catch{renderer=new DepthRenderer()}let mesh,type='';return {paint(ctx,age,params){const next=params.primitive||'box';if(type!==next){if(mesh){scene.remove(mesh);mesh.geometry.dispose();mesh.material.dispose()}const geo=next==='sphere'?new T.SphereGeometry(1.4,20,14):next==='torus'?new T.TorusGeometry(1.1,.4,12,24):next==='cone'?new T.ConeGeometry(1.3,2.7,20):new T.BoxGeometry(2,2,2);mesh=new T.Mesh(geo,new T.MeshStandardMaterial({color:params.objectColor||'#b9a5eb',roughness:.35,metalness:.2}));scene.add(mesh);type=next}mesh.material.color.set(params.objectColor||'#b9a5eb');mesh.rotation.set(age*(params.spinX||0),age*(params.spinY??.35),age*(params.spinZ||0));renderer.render(scene,camera);if(renderer.software){const data=renderer.ctx.getImageData(0,0,640,360);for(let i=0;i<data.data.length;i+=4)if(data.data[i]===15&&data.data[i+1]===21&&data.data[i+2]===31)data.data[i+3]=0;renderer.ctx.putImageData(data,0,0)}ctx.drawImage(renderer.domElement,0,0,960,540)}}}
